import base64
import io
import os
from typing import Any, Dict, List, Optional, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _load_image_bytes(image: Union[str, bytes, bytearray, io.BytesIO, io.BufferedIOBase]) -> bytes:
    if isinstance(image, (bytes, bytearray)):
        return bytes(image)
    if isinstance(image, str):
        if image.startswith("http://") or image.startswith("https://"):
            import requests

            resp = requests.get(image, timeout=30)
            resp.raise_for_status()
            return resp.content
        with open(image, "rb") as f:
            return f.read()
    if isinstance(image, io.BytesIO):
        return image.getvalue()
    if hasattr(image, "read"):
        return image.read()
    raise TypeError("Unsupported image input type.")


def _labels_from_rekognition(response: Dict[str, Any]) -> List[Dict[str, Any]]:
    labels = []
    for label in response.get("Labels", []):
        labels.append(
            {
                "name": label.get("Name"),
                "confidence": float(label.get("Confidence", 0.0)),
                "parents": [p.get("Name") for p in label.get("Parents", []) if p.get("Name")],
            }
        )
    return labels


def _text_from_rekognition(response: Dict[str, Any]) -> List[Dict[str, Any]]:
    text_items = []
    for item in response.get("TextDetections", []):
        text_items.append(
            {
                "text": item.get("DetectedText"),
                "type": item.get("Type"),
                "confidence": float(item.get("Confidence", 0.0)),
            }
        )
    return text_items


def _policy_signals(labels: List[Dict[str, Any]], texts: List[Dict[str, Any]]) -> Dict[str, Any]:
    risky_keywords = {
        "weapon",
        "gun",
        "knife",
        "blood",
        "drugs",
        "drug",
        "nude",
        "nudity",
        "explicit",
        "sexual",
        "violence",
        "dead body",
        "corpse",
        "hate",
        "swastika",
        "bomb",
        "explosion",
        "firearm",
        "pistol",
        "rifle",
    }

    matched = set()
    for item in labels:
        name = (item.get("name") or "").lower()
        parents = " ".join((p or "").lower() for p in item.get("parents", []))
        blob = f"{name} {parents}"
        for kw in risky_keywords:
            if kw in blob:
                matched.add(kw)

    for item in texts:
        txt = (item.get("text") or "").lower()
        for kw in risky_keywords:
            if kw in txt:
                matched.add(kw)

    unsafe = len(matched) > 0
    return {
        "unsafe": unsafe,
        "matched_signals": sorted(matched),
    }


def analyze_image_safety(
    image: Union[str, bytes, bytearray, io.BytesIO, io.BufferedIOBase],
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Checks a static image for unsafe or policy-sensitive visual content using Amazon Rekognition.

    Inputs:
        image: Local file path, URL, bytes, or file-like object.
        region_name: Optional AWS region, defaults to AWS_REGION or us-east-1.

    Returns:
        dict containing labels, text detections, and a safety assessment.
    """
    aws_region = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1"
    rekognition = boto3.client("rekognition", region_name=aws_region)

    image_bytes = _load_image_bytes(image)
    image_payload = {"Bytes": image_bytes}

    try:
        label_resp = rekognition.detect_labels(
            Image=image_payload,
            MaxLabels=50,
            MinConfidence=50.0,
        )
        text_resp = rekognition.detect_text(Image=image_payload)
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Amazon Rekognition request failed: {e}") from e

    labels = _labels_from_rekognition(label_resp)
    texts = _text_from_rekognition(text_resp)

    safety = _policy_signals(labels, texts)

    return {
        "provider": "amazon_rekognition",
        "region": aws_region,
        "unsafe": safety["unsafe"],
        "matched_signals": safety["matched_signals"],
        "labels": labels,
        "text_detections": texts,
        "raw": {
            "label_response": label_resp,
            "text_response": text_resp,
        },
    }
